const isWebhook = Boolean($json.body !== undefined || $json.headers !== undefined);
const body = isWebhook ? ($json.body || {}) : {};
return [{ json: {
  triggered_by: isWebhook ? 'manual' : 'schedule',
  force: Boolean(body.force),
  now: Date.now()
} }];

const t = $json;
const body = t.body || {};
const httpOk = (t.statusCode >= 200 && t.statusCode < 300);
const acquired = httpOk && body.acquired === true;
const proceed = acquired || t.force === true;
return [{ json: { proceed, lock_acquired: acquired, forced_through: (!acquired && t.force === true), triggered_by: t.triggered_by, now: t.now } }];

const t = $json;
const body = (t.statusCode >= 200 && t.statusCode < 300) ? (t.body || {}) : {};
const BOOTSTRAP_LOOKBACK_MS = 15 * 60 * 1000;
const since = body.last_checked_at || (t.now - BOOTSTRAP_LOOKBACK_MS);
return [{ json: { since, until: t.now, triggered_by: t.triggered_by, forced_through: t.forced_through,
  cursor: null, accumulated: [], pages_fetched: 0 } }];

const t = $json;
return [{ json: { alert_type: 'monitor_degraded', message: `:rotating_light: Self-healing monitor could not reach the n8n API (status ${t.statusCode}). Skipping this poll cycle without advancing the watermark, so the next cycle retries the same window.`,
  since: t.since, triggered_by: t.triggered_by } }];

const t = $json;
const page = t.body || {};
const accumulated = (t.accumulated || []).concat(page.data || []);
return [{ json: { since: t.since, until: t.until, triggered_by: t.triggered_by, forced_through: t.forced_through,
  accumulated, cursor: page.nextCursor || null, pages_fetched: (t.pages_fetched || 0) + 1 } }];

const t = $json;
const execs = t.accumulated || [];
const distinctWorkflows = new Set(execs.map(e => e.workflowId));
const STORM_THRESHOLD = 5;
const is_storm = distinctWorkflows.size >= STORM_THRESHOLD;
return [{ json: { since: t.since, until: t.until, triggered_by: t.triggered_by,
  executions: execs, total_failed: execs.length, distinct_workflow_count: distinctWorkflows.size, is_storm } }];

const t = $json;
return (t.executions || []).map(e => ({ json: {
  execution_id: e.id, workflow_id: e.workflowId, workflow_name: e.workflowName || e.workflowId,
  started_at: e.startedAt, stopped_at: e.stoppedAt, is_storm: t.is_storm
} }));

const t = $json;
const detail = (t.statusCode >= 200 && t.statusCode < 300) ? (t.body || {}) : {};
const lastNode = detail.data?.resultData?.lastNodeExecuted || 'unknown';
const rawError = detail.data?.resultData?.error || {};
const message = (rawError.message || rawError.description || '').toString();
const httpCode = rawError.httpCode || rawError.statusCode || null;
const lower = message.toLowerCase();
const TRANSIENT_HINTS = ['timeout', 'timed out', 'econnreset', 'econnrefused', 'enotfound', 'socket hang up', '429', '502', '503', '504', 'rate limit'];
const PERMANENT_HINTS = ['validation', 'unauthorized', '401', '403', 'invalid credentials', 'bad request', '400', 'not found', '404', 'unprocessable', '422'];
let failure_type = 'unknown';
if (TRANSIENT_HINTS.some(h => lower.includes(h)) || (httpCode >= 500)) failure_type = 'transient';
else if (PERMANENT_HINTS.some(h => lower.includes(h)) || (httpCode >= 400 && httpCode < 500)) failure_type = 'permanent';
return [{ json: { execution_id: t.execution_id, workflow_id: t.workflow_id, workflow_name: t.workflow_name,
  is_storm: t.is_storm, failed_node: lastNode, error_message: message.slice(0, 500), failure_type, fetched_ok: (t.statusCode >= 200 && t.statusCode < 300) } }];

const crypto = require('crypto');
const t = $json;
const raw = `${t.workflow_id}::${t.failed_node}::${t.failure_type}`;
const incident_key = crypto.createHash('sha256').update(raw).digest('hex').slice(0, 24);
return [{ json: { ...t, incident_key } }];

const t = $json;
const MAX_RETRIES = 3;
const found = t.statusCode >= 200 && t.statusCode < 300;
const state = found ? (t.body || {}) : {};
const retries_used = state.retries_used || 0;
const next_retry_at = state.next_retry_at || 0;
const now = Date.now();
let action;
if (t.is_storm) action = 'suppress_storm';
else if (t.failure_type === 'permanent') action = 'escalate_permanent';
else if (t.failure_type === 'unknown') action = 'escalate_unknown';
else if (retries_used >= MAX_RETRIES) action = 'escalate_exhausted';
else if (now < next_retry_at) action = 'wait_backoff';
else action = 'retry';
return [{ json: { execution_id: t.execution_id, workflow_id: t.workflow_id, workflow_name: t.workflow_name,
  incident_key: t.incident_key, failed_node: t.failed_node, error_message: t.error_message, failure_type: t.failure_type,
  retries_used, next_retry_at, action } }];

const t = $json;
const retries_used = (t.retries_used || 0) + 1;
const BASE_MS = 5 * 60 * 1000; // 5 min
const backoff_ms = BASE_MS * Math.pow(3, retries_used - 1); // 5m, 15m, 45m
const jitter_ms = Math.floor(Math.random() * 30000);
const next_retry_at = Date.now() + backoff_ms + jitter_ms;
return [{ json: { incident_key: t.incident_key, execution_id: t.execution_id, workflow_id: t.workflow_id,
  retries_used, next_retry_at, status: 'retrying' } }];

const t = $json;
const REASON_TEXT = { permanent_error: 'a permanent error (looks like a code/config bug, not transient)',
  unknown_error: 'an unrecognized failure type (needs eyes, not blind auto-retry)',
  retries_exhausted: `retries exhausted (${t.retries_used} attempts, still failing)`,
  retry_dispatch_failed: 'the auto-retry call itself failed to dispatch' };
const reason_text = REASON_TEXT[t.escalate_reason] || t.escalate_reason;
const text = `:warning: *Workflow needs attention*\n*Workflow:* ${t.workflow_name} (${t.workflow_id})\n*Failed node:* ${t.failed_node}\n*Reason:* ${reason_text}\n*Error:* ${t.error_message}\n*Execution:* ${t.execution_id}`;
return [{ json: { ...t, text } }];

const items = $json.data || [];
const counts = { retried: 0, escalated: 0, escalation_suppressed_cooldown: 0, waiting_backoff: 0, suppressed_storm: 0, skipped_inactive_workflow: 0 };
for (const it of items) { if (counts[it.outcome] !== undefined) counts[it.outcome]++; }
return [{ json: { outcomes: items, counts } }];

const t = $json;
const list = (t.statusCode >= 200 && t.statusCode < 300) ? (t.body?.incidents || []) : [];
return [{ json: { incidents: list } }];

const t = $json;
const text = `:white_check_mark: *Recovered* -- ${t.workflow_name || t.workflow_id} is succeeding again (incident ${t.incident_key}, was failing at node ${t.failed_node}). Marking resolved.`;
return [{ json: { ...t, text } }];

const items = $json.data || [];
const recovered = items.filter(i => i.outcome === 'recovered');
const still_open_count = items.filter(i => i.outcome === 'still_open').length;
return [{ json: { recovered, still_open_count } }];

const t = $json;
const triggered_by = $('Compute Poll Window').first().json.triggered_by;
return [{ json: { status: 'completed', triggered_by, counts: t.counts, recovered: (t.recovered || []).map(r => r.workflow_id),
  still_open_count: t.still_open_count, checked_at: Date.now() } }];
